using System;
using System.Collections.Generic;
using System.Reflection;
using LastRail.Presentation.Battle;
using NUnit.Framework;

public sealed class ReinaCinematicPlaybackTests {
 static readonly long Second=TimeSpan.TicksPerSecond;
 static object Call(object target,string method,params object[] args){try{return target.GetType().GetMethod(method).Invoke(target,args);}catch(TargetInvocationException error){throw error.InnerException;}}
 sealed class Fixture {
  internal readonly object Player;internal IDisposable Lease;internal int Started,Stopped,Ended,Skipped;internal readonly List<bool> Pauses=new List<bool>();internal readonly List<float> Gains=new List<float>();internal readonly List<Exception> Failures=new List<Exception>();
  internal bool ThrowStart,ThrowStop,ThrowPause;internal Action OnSkipped,OnEnded;
  internal Fixture(){var type=typeof(UltimatePresentationSession).Assembly.GetType("LastRail.Presentation.Battle.ReinaCinematicPlayback");Assert.NotNull(type,"Missing approved Reina cinematic playback clock.");Player=Activator.CreateInstance(type,new object[]{(Action)(()=>{Started++;if(ThrowStart)throw new InvalidOperationException("explicit-test-start");}),(Action<bool>)(paused=>{Pauses.Add(paused);if(ThrowPause)throw new InvalidOperationException("explicit-test-pause");}),(Action<float>)(gain=>Gains.Add(gain)),(Action)(()=>{Stopped++;if(ThrowStop)throw new InvalidOperationException("explicit-test-stop");})});}
  internal void Begin(){Lease=(IDisposable)Call(Player,"Begin",(Action)(()=>{Ended++;OnEnded?.Invoke();}),(Action)(()=>{Skipped++;OnSkipped?.Invoke();}),(Action<Exception>)(e=>Failures.Add(e)));}
  internal void Advance(long presentation,long output=0)=>Call(Player,"Advance",presentation,output);
  internal void Pause(bool value)=>Call(Player,"SetPaused",value);
  internal void Skip()=>Call(Player,"Skip");internal void Dispose()=>Call(Player,"Dispose");
 }
 [Test] public void OriginalDepthStartsAtTwoPointFiveAndStandardEndsAtEightPointNineFive(){var f=new Fixture();f.Begin();f.Advance(25*Second/10-1);Assert.AreEqual(0,f.Started);f.Advance(1);Assert.AreEqual(1,f.Started);f.Advance(645*Second/100-1);Assert.AreEqual(0,f.Ended);f.Advance(1);Assert.AreEqual(1,f.Ended);Assert.AreEqual(1,f.Stopped);f.Advance(Second);f.Dispose();Assert.AreEqual(1,f.Started);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(1,f.Ended);}
 [Test] public void SkipReleasesSessionHoldImmediatelyWhileOwnedAudioFadesForEightyOutputMilliseconds(){var f=new Fixture();int released=0;using(var session=new UltimatePresentationSession("test-original-commit",1,LastRail.Battle.CombatPresentationMode.Full,()=>true,()=>true,()=>true,()=>true,()=>{},()=>new Lease(()=>released++),(kind,visible,end,skip,fail)=>(IDisposable)Call(f.Player,"Begin",end,skip,fail),valid=>{},e=>Assert.Fail(e.ToString()))){session.Start();f.Advance(25*Second/10);f.Skip();Assert.AreEqual(1,released);Assert.AreEqual(0,f.Stopped);f.Advance(100*Second,40*TimeSpan.TicksPerMillisecond);Assert.That(f.Gains[f.Gains.Count-1],Is.EqualTo(.5f).Within(.0001));Assert.AreEqual(0,f.Stopped);f.Advance(0,40*TimeSpan.TicksPerMillisecond);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(1,released);}f.Dispose();Assert.AreEqual(1,f.Stopped);}
 [Test] public void SkipBeforeDepthNeverStartsOrSeeksToRemainingExplosions(){var f=new Fixture();f.Begin();f.Advance(Second);f.Skip();f.Lease.Dispose();f.Advance(100*Second,100*Second);Assert.AreEqual(0,f.Started);Assert.AreEqual(0,f.Stopped);Assert.AreEqual(1,f.Skipped);Assert.AreEqual(0,f.Ended);}
 [Test] public void RepeatedSkipAndReturnedSessionLeaseCannotRestartFade(){var f=new Fixture();f.Begin();f.Advance(3*Second);f.Skip();f.Lease.Dispose();f.Advance(0,40*TimeSpan.TicksPerMillisecond);f.Skip();f.Lease.Dispose();f.Advance(0,40*TimeSpan.TicksPerMillisecond);Assert.AreEqual(1,f.Skipped);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(1,f.Started);}
 [TestCase(false)][TestCase(true)] public void PausePreservesPositionAndResumeNeverRestartsDepth(bool afterStart){var f=new Fixture();f.Begin();f.Advance(afterStart?3*Second:Second);f.Pause(true);f.Pause(true);f.Advance(20*Second,20*Second);Assert.AreEqual(0,f.Ended);Assert.AreEqual(afterStart?1:0,f.Started);f.Pause(false);f.Advance(afterStart?595*Second/100:15*Second/10);Assert.AreEqual(afterStart?1:0,f.Ended);Assert.AreEqual(1,f.Started);if(afterStart)CollectionAssert.AreEqual(new[]{true,false},f.Pauses);}
 [Test] public void PausedSkipFadeResumesItsRemainingOutputDuration(){var f=new Fixture();f.Begin();f.Advance(3*Second);f.Skip();f.Advance(0,40*TimeSpan.TicksPerMillisecond);f.Pause(true);f.Advance(10*Second,10*Second);Assert.AreEqual(0,f.Stopped);f.Pause(false);f.Advance(0,40*TimeSpan.TicksPerMillisecond);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(1,f.Started);}
 [Test] public void OutputClockDoesNotAdvancePresentationAndPresentationClockDoesNotAdvanceFade(){var f=new Fixture();f.Begin();f.Advance(0,100*Second);Assert.AreEqual(0,f.Started);f.Advance(25*Second/10);f.Skip();f.Advance(100*Second,0);Assert.AreEqual(0,f.Stopped);f.Advance(0,80*TimeSpan.TicksPerMillisecond);Assert.AreEqual(1,f.Stopped);}
 [TestCase(false)][TestCase(true)] public void OwnerDisposeStopsImmediatelyEvenDuringFade(bool fading){var f=new Fixture();f.Begin();f.Advance(3*Second);if(fading)f.Skip();f.Dispose();f.Dispose();f.Lease.Dispose();f.Advance(100*Second,100*Second);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(0,f.Ended);Assert.AreEqual(fading?1:0,f.Skipped);}
 [Test] public void SessionCancellationBeforeSkipHardStopsItsOwnedPlayback(){var f=new Fixture();f.Begin();f.Advance(3*Second);f.Lease.Dispose();f.Advance(100*Second,100*Second);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(0,f.Ended);Assert.AreEqual(0,f.Skipped);}
 [Test] public void StartFailureCleansPartialAudioAndReportsExactlyOnce(){var f=new Fixture{ThrowStart=true};f.Begin();f.Advance(25*Second/10);f.Advance(100*Second,100*Second);f.Dispose();Assert.AreEqual(1,f.Started);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(1,f.Failures.Count);Assert.AreEqual(0,f.Ended);}
 [Test] public void PauseFailureStillCleansAndReportsOriginalCause(){var f=new Fixture();f.Begin();f.Advance(3*Second);f.ThrowPause=true;f.Pause(true);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(1,f.Failures.Count);StringAssert.Contains("pause",f.Failures[0].ToString());}
 [Test] public void CleanupErrorCannotKeepSessionHoldOrRestartAudio(){var f=new Fixture{ThrowStop=true};f.Begin();f.Advance(3*Second);f.Dispose();f.Dispose();Assert.AreEqual(1,f.Stopped);Assert.AreEqual(1,f.Failures.Count);}
 [Test] public void ReentrantSkipCallbackMayHardDisposeWithoutLeakingAudio(){var f=new Fixture();f.OnSkipped=f.Dispose;f.Begin();f.Advance(3*Second);f.Skip();f.Advance(0,80*TimeSpan.TicksPerMillisecond);Assert.AreEqual(1,f.Stopped);Assert.AreEqual(1,f.Skipped);}
 [Test] public void InvalidClockInputDoesNotAdvancePlayback(){var f=new Fixture();f.Begin();Assert.Throws<ArgumentOutOfRangeException>(()=>f.Advance(-1));Assert.Throws<ArgumentOutOfRangeException>(()=>f.Advance(0,-1));Assert.AreEqual(0,f.Started);}
 [Test] public void NoReplayAfterCompletionAndNoBeginAfterOwnerDisposal(){var f=new Fixture();f.Begin();f.Advance(25*Second/10);f.Advance(645*Second/100);Assert.Throws<InvalidOperationException>(f.Begin);var other=new Fixture();other.Dispose();Assert.Throws<ObjectDisposedException>(other.Begin);}
 [TestCase(0)][TestCase(1)][TestCase(2)][TestCase(3)] public void EveryOwnedAudioPortIsRequired(int missing){var f=new Fixture();object[] ports={(Action)(()=>{}),(Action<bool>)(_=>{}),(Action<float>)(_=>{}),(Action)(()=>{})};ports[missing]=null;var error=Assert.Throws<TargetInvocationException>(()=>Activator.CreateInstance(f.Player.GetType(),ports));Assert.IsInstanceOf<ArgumentNullException>(error.InnerException);}
 sealed class Lease:IDisposable {Action release;internal Lease(Action release){this.release=release;}public void Dispose(){var old=release;release=null;old?.Invoke();}}
}
